    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]; edge=False
            while q:
                y,x=q.popleft(); cells.append((y,x))
